    <script>
        // Canvas setup
        const canvas = document.getElementById('canvas');
        const ctx = canvas.getContext('2d');
        const info = document.getElementById('info');

        // Set canvas to full window size
        function resizeCanvas() {
            canvas.width = window.innerWidth;
            canvas.height = window.innerHeight;
        }
        window.addEventListener('resize', resizeCanvas);
        resizeCanvas();

        // Cube definition
        // 8 vertices of a cube centered at origin
        const vertices = [
            [-1, -1, -1], // 0
            [1, -1, -1],  // 1
            [1, 1, -1],   // 2
            [-1, 1, -1],  // 3
            [-1, -1, 1],  // 4
            [1, -1, 1],   // 5
            [1, 1, 1],    // 6
            [-1, 1, 1]    // 7
        ];

        // Faces as triangles (each face split into 2 triangles)
        // Each triangle is defined by 3 vertex indices
        const triangles = [
            // Front face (z = -1)
            [0, 1, 2], [0, 2, 3],
            // Back face (z = 1)
            [4, 7, 6], [4, 6, 5],
            // Right face (x = 1)
            [1, 5, 6], [1, 6, 2],
            // Left face (x = -1)
            [0, 3, 7], [0, 7, 4],
            // Top face (y = 1)
            [3, 2, 6], [3, 6, 7],
            // Bottom face (y = -1)
            [0, 4, 5], [0, 5, 1]
        ];

        // Light source - moving in a circle
        let lightAngle = 0;
        const lightRadius = 5;
        const lightSpeed = 0.01;

        // Camera parameters
        const cameraDistance = 8;
        const fov = 500;

        // Rotation angles
        let rotationX = 0;
        let rotationY = 0;
        let rotationZ = 0;
        let isPaused = false;

        // Wireframe mode
        let wireframe = false;

        // FPS tracking
        let lastTime = 0;
        let frameCount = 0;
        let fps = 0;

        // Matrix operations
        function multiplyMatrix(m1, m2) {
            const result = [];
            for (let i = 0; i < 3; i++) {
                result[i] = [];
                for (let j = 0; j < 3; j++) {
                    result[i][j] = 0;
                    for (let k = 0; k < 3; k++) {
                        result[i][j] += m1[i][k] * m2[k][j];
                    }
                }
            }
            return result;
        }

        function rotateX(angle) {
            const cos = Math.cos(angle);
            const sin = Math.sin(angle);
            return [
                [1, 0, 0],
                [0, cos, -sin],
                [0, sin, cos]
            ];
        }

        function rotateY(angle) {
            const cos = Math.cos(angle);
            const sin = Math.sin(angle);
            return [
                [cos, 0, sin],
                [0, 1, 0],
                [-sin, 0, cos]
            ];
        }

        function rotateZ(angle) {
            const cos = Math.cos(angle);
            const sin = Math.sin(angle);
            return [
                [cos, -sin, 0],
                [sin, cos, 0],
                [0, 0, 1]
            ];
        }

        function transformPoint(point, matrix) {
            return [
                matrix[0][0] * point[0] + matrix[0][1] * point[1] + matrix[0][2] * point[2],
                matrix[1][0] * point[0] + matrix[1][1] * point[1] + matrix[1][2] * point[2],
                matrix[2][0] * point[0] + matrix[2][1] * point[1] + matrix[2][2] * point[2]
            ];
