                lightDir[1] / lightLength,
                lightDir[2] / lightLength
            ];

            // Dot product (Lambert's cosine law)
            const dot = normNormal[0] * normLight[0] + normNormal[1] * normLight[1] + normNormal[2] * normLight[2];

            // Clamp to [0, 1] for diffuse lighting
            return Math.max(0, dot);
        }

        // Calculate face normal
