                v2[1] - v1[1],
                v2[2] - v1[2]
            ];

            const edge2 = [
                v3[0] - v1[0],
                v3[1] - v1[1],
                v3[2] - v1[2]
            ];

            // Cross product
            const normal = [
                edge1[1] * edge2[2] - edge1[2] * edge2[1],
                edge1[2] * edge2[0] - edge1[0] * edge2[2],
                edge1[0] * edge2[1] - edge1[1] * edge2[0]
            ];

            return normal;
        }

        // Gouraud shading - interpolate colors across triangle
        function drawTriangle(p1, p2, p3, c1, c2, c3) {
            // If any point is null (behind camera), skip
            if (!p1 || !p2 || !p3) return;

            // Draw wireframe if enabled
            if (wireframe) {
                ctx.beginPath();
                ctx.moveTo(p1[0] + canvas.width / 2, p1[1] + canvas.height / 2);
                ctx.lineTo(p2[0] + canvas.width / 2, p2[1] + canvas.height / 2);
                ctx.lineTo(p3[0] + canvas.width / 2, p3[1] + canvas.height / 2);
                ctx.closePath();
                ctx.strokeStyle = 'rgba(255, 255, 255, 0.3)';
                ctx.stroke();
            }

            // For Gouraud shading, we need to fill the triangle with interpolated colors
            // We'll use a simple scanline approach

            // Sort vertices by y-coordinate
            let vertices = [
                {point: p1, color: c1},
                {point: p2, color: c2},
