                    rightColor[1] = color0[1] + tRight * (color2[1] - color0[1]);
                    rightColor[2] = color0[2] + tRight * (color2[2] - color0[2]);

                    leftX = v1.point[0] + slope12 * (y - v1.point[1]);
                    rightX = v0.point[0] + slope02 * (y - v0.point[1]);

                    // Draw scanline
