                            const t = (x - leftX) / width;
                            const r = leftColor[0] + t * (rightColor[0] - leftColor[0]);
                            const g = leftColor[1] + t * (rightColor[1] - leftColor[1]);
                            const b = leftColor[2] + t * (rightColor[2] - leftColor[2]);

                            ctx.fillStyle = `rgb(${Math.floor(r)}, ${Math.floor(g)}, ${Math.floor(b)})`;
                            ctx.fillRect(x + canvas.width / 2, y + canvas.height / 2, 1, 1);
                        }
                    }
                }
            }
        }

        // Animation loop
        function animate(currentTime) {
            // FPS calculation
            frameCount++;
            if (currentTime - lastTime >= 1000) {
                fps = Math.round((frameCount * 1000) / (currentTime - lastTime));
                frameCount = 0;
                lastTime = currentTime;
                info.textContent = `FPS: ${fps}\nPress W for wireframe, P to pause`;
            }

            // Update light position
