        document.addEventListener('keydown', (event) => {
            if (event.key === 'w' || event.key === 'W') {
                wireframe = !wireframe;
            } else if (event.key === 'p' || event.key === 'P') {
                isPaused = !isPaused;
            }
        });

        // Start animation
        requestAnimationFrame(animate);
    </script>
